-- База данных для приложения «Бронирование билетов в кинотеатр»
-- Учебная практика УП.02, задание № 11

DROP DATABASE IF EXISTS cinema;
CREATE DATABASE cinema CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE cinema;

CREATE TABLE genres (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(50) NOT NULL UNIQUE
) ENGINE = InnoDB;

CREATE TABLE movies (
    id INT AUTO_INCREMENT PRIMARY KEY,
    title VARCHAR(150) NOT NULL,
    genre_id INT NOT NULL,
    duration_min SMALLINT NOT NULL,
    age_rating ENUM('0+', '6+', '12+', '16+', '18+') NOT NULL DEFAULT '0+',
    release_year SMALLINT NOT NULL,
    description TEXT,
    CONSTRAINT fk_movies_genre FOREIGN KEY (genre_id) REFERENCES genres (id),
    CONSTRAINT chk_movies_duration CHECK (duration_min BETWEEN 1 AND 400)
) ENGINE = InnoDB;

CREATE TABLE halls (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(50) NOT NULL UNIQUE,
    hall_type ENUM('Обычный', 'VIP', 'IMAX') NOT NULL DEFAULT 'Обычный',
    rows_count TINYINT UNSIGNED NOT NULL,
    seats_per_row TINYINT UNSIGNED NOT NULL,
    CONSTRAINT chk_halls_size CHECK (rows_count BETWEEN 1 AND 30 AND seats_per_row BETWEEN 1 AND 40)
) ENGINE = InnoDB;

CREATE TABLE sessions (
    id INT AUTO_INCREMENT PRIMARY KEY,
    movie_id INT NOT NULL,
    hall_id INT NOT NULL,
    start_time DATETIME NOT NULL,
    price DECIMAL(8, 2) NOT NULL,
    CONSTRAINT fk_sessions_movie FOREIGN KEY (movie_id) REFERENCES movies (id),
    CONSTRAINT fk_sessions_hall FOREIGN KEY (hall_id) REFERENCES halls (id),
    CONSTRAINT chk_sessions_price CHECK (price > 0),
    INDEX idx_sessions_start (start_time)
) ENGINE = InnoDB;

CREATE TABLE tickets (
    id INT AUTO_INCREMENT PRIMARY KEY,
    session_id INT NOT NULL,
    row_num TINYINT UNSIGNED NOT NULL,
    seat_num TINYINT UNSIGNED NOT NULL,
    customer_name VARCHAR(100) NOT NULL,
    customer_phone VARCHAR(20) NOT NULL,
    price DECIMAL(8, 2) NOT NULL,
    status ENUM('Забронирован', 'Оплачен') NOT NULL DEFAULT 'Забронирован',
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_tickets_session FOREIGN KEY (session_id) REFERENCES sessions (id) ON DELETE CASCADE,
    CONSTRAINT uq_tickets_seat UNIQUE (session_id, row_num, seat_num)
) ENGINE = InnoDB;


